arguments.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Description is required.")]
    [StringLength(500, ErrorMessage = "Description must be 500 characters or fewer.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple, classic pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes over the dough.", "Tear mozzarella and distribute evenly.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated Pecorino and pepper.", "Toss hot pasta with pancetta off the heat.", "Pour egg mixture over pasta and toss quickly.", "Serve immediately with extra cheese and pepper."],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer 15 minutes.", "Stir in cream and cooked chicken.", "Simmer 10 minutes and serve with rice."],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with vegetables, peanuts, and tangy sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Green onions", "Peanuts", "Lime", "Pad Thai sauce", "Eggs"],
                Steps = ["Soak rice noodles in warm water for 30 minutes.", "Press and cube tofu, then pan-fry until golden.", "Scramble eggs in the same pan.", "Add noodles and Pad Thai sauce, toss to coat.", "Add bean sprouts and green onions.", "Serve topped with crushed peanuts and lime wedges."],
                TotalRatings = 6, RatingSum = 25
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm tortillas in a dry pan or oven.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa.", "Serve immediately."],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich individual chocolate cakes with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla, then fold into chocolate.", "Add flour and mix until just combined.", "Pour into greased ramekins.", "Bake 12-14 minutes until edges are set but center is soft."],
                TotalRatings = 20, RatingSum = 95
            },
            new Recipe
            {
                Id = 7, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh avocado dip with lime, cilantro, and jalapeño.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve and pit avocados, scoop into a bowl.", "Mash to desired consistency.", "Stir in diced onion, jalapeño, tomato, and cilantro.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 8, Title = "Mango Sticky Rice", Category = "Thai",
                Description = "Sweet sticky rice served with fresh mango and coconut cream.",
                Ingredients = ["Sticky rice", "Coconut milk", "Sugar", "Salt", "Ripe mango"],
                Steps = ["Soak sticky rice overnight, then steam for 20 minutes.", "Heat coconut milk with sugar and salt.", "Pour half the coconut sauce over the cooked rice.", "Let rice absorb the sauce for 30 minutes.", "Slice mango and arrange alongside rice.", "Drizzle remaining coconut sauce on top."],
                TotalRatings = 7, RatingSum = 32
            },
            new Recipe
            {
                Id = 9, Title = "Palak Paneer", Category = "Indian",
                Description = "Creamy spinach curry with cubes of paneer cheese.",
                Ingredients = ["Spinach", "Paneer", "Onion", "Tomato", "Garlic", "Ginger", "Garam masala", "Cream"],
                Steps = ["Blanch spinach and blend into a smooth purée.", "Fry paneer cubes until golden, set aside.", "Sauté onion, garlic, and ginger until soft.", "Add tomato and spices, cook 5 minutes.", "Stir in spinach purée and simmer.", "Add paneer and cream, cook 5 more minutes."],
                TotalRatings = 11, RatingSum = 48
            },
            new Recipe
            {
                Id = 10, Title = "Tiramisu", Category = "Desserts",
                Description = "Classic Italian layered dessert with espresso-soaked ladyfingers.",
                Ingredients = ["Ladyfingers", "Espresso", "Mascarpone", "Eggs", "Sugar", "Cocoa powder", "Marsala wine"],
                Steps = ["Brew espresso and let it cool, mix with Marsala.", "Separate eggs; whisk yolks with sugar until pale.", "Fold mascarpone into yolk mixture.", "Whip egg whites to stiff peaks and fold in.", "Dip ladyfingers in espresso and layer in a dish.", "Spread mascarpone mixture on top, repeat layers, and dust with cocoa. Chill 4 hours."],
                TotalRatings = 18, RatingSum = 85
            }
        ];
        _nextId = 11;
    }

    public static IReadOnlyList<string> Categories { get; } =
        ["Italian", "Indian", "Thai", "Mexican", "Desserts"];

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        });
    }
}

