@page "/"

@using RecipeShare.Services

@inject RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var category in RecipeService.Categories)
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body d-flex flex-column">
                    <h3 class="card-title">@CategoryEmoji(category) @category</h3>
                    <p class="card-text text-muted">
                        @RecipeService.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="category/@category" class="btn btn-primary mt-auto">Browse @category</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🥘",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

@using RecipeShare.Models
@using RecipeShare.Services

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body d-flex flex-column">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text">@recipe.Description</p>
                        <div class="mt-auto d-flex justify-content-between align-items-center">
                            <span class="text-warning">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                }
                                <small class="text-muted ms-1">(@recipe.TotalRatings)</small>
                            </span>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">&larr; Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"

@using RecipeShare.Models
@using RecipeShare.Services

@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (_recipe is null)
{
    <h2>Recipe not found</h2>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-link">&larr; Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    <StarRating RecipeId="_recipe.Id" @rendermode="InteractiveServer" />

    <div class="row mt-4">
        <div class="col-md-5">
            <h3>Ingredients</h3>
            <ul class="list-group list-group-flush">
                @foreach (var ingredient in _recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-7">
            <h3>Steps</h3>
            <ol class="list-group list-group-numbered list-group-flush">
                @foreach (var step in _recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <a href="category/@_recipe.Category" class="btn btn-link mt-3">&larr; Back to @_recipe.Category</a>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(RecipeId);
    }
}

@using RecipeShare.Services

@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded bg-light">
