@page "/recipe/{RecipeId:int}"

@using RecipeShare.Models
@using RecipeShare.Services

@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (_recipe is null)
{
    <h2>Recipe not found</h2>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-link">&larr; Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    <StarRating RecipeId="_recipe.Id" @rendermode="InteractiveServer" />

    <div class="row mt-4">
        <div class="col-md-5">
            <h3>Ingredients</h3>
            <ul class="list-group list-group-flush">
                @foreach (var ingredient in _recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-7">
            <h3>Steps</h3>
            <ol class="list-group list-group-numbered list-group-flush">
                @foreach (var step in _recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <a href="category/@_recipe.Category" class="btn btn-link mt-3">&larr; Back to @_recipe.Category</a>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(RecipeId);
    }
}

@using RecipeShare.Services

@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded bg-light">
    <h5 class="mb-2">Rate this recipe</h5>
    <div style="font-size: 1.8rem; cursor: pointer; user-select: none;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => SubmitRating(star)"
                  @onmouseover="() => _hover = star"
                  @onmouseout="() => _hover = 0"
                  style="color: @(star <= DisplayStars ? "#ffc107" : "#ddd");">★</span>
        }
    </div>
    @if (_submitted)
    {
        <div class="alert alert-success mt-2 py-1 px-2 d-inline-block" role="alert">
            Thanks for rating! You gave @_selectedRating star(s).
        </div>
    }
    <div class="text-muted small mt-1">
        Average: @_average.ToString("0.0") / 5 (@_totalRatings ratings)
    </div>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _hover;
    private int _selectedRating;
    private bool _submitted;
    private double _average;
    private int _totalRatings;

    private int DisplayStars => _hover > 0 ? _hover : _selectedRating;

    protected override void OnParametersSet()
    {
        RefreshStats();
    }

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        _selectedRating = stars;
        _submitted = true;
        RefreshStats();
    }

    private void RefreshStats()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            _average = recipe.AverageRating;
            _totalRatings = recipe.TotalRatings;
        }
    }
}

